\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
For every dimension bound $d$ and $\varepsilon\geq 0$, does there exist a finite set of complementary indices $N_d(\varepsilon)$ such that every $\varepsilon$-log-canonical variety $X$ of dimension at most $d$, with $-K_X$ nef and big over $Z$, has a general bounded complement $(X,D/n)$ that is $\varepsilon$-log-canonical?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2004/31}{[S2]}.

\subsection{Short English statement}
For every dimension bound $d$ and $\varepsilon\geq 0$, does there exist a finite set of complementary indices $N_d(\varepsilon)$ such that every $\varepsilon$-log-canonical variety $X$ of dimension at most $d$, with $-K_X$ nef and big over $Z$, has a general bounded complement $(X,D/n)$ that is $\varepsilon$-log-canonical?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30000075 (OWR-733-007). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2004/31}.
\end{itemize}
\label{end:30000075}

